mapper.select:
select t1.* from (select p.CONTRACT_NUMBER, p.CONTRACT_ID, p.PLAN_ID, p.ACTUAL_FINISH_DATE, p.PRJ_REGULAR_ASSIGN, p.CREATED_BY, p.PLAN_CHECK_DATE, ( SELECT scvb.meaning AS value_name FROM sys_code_value_b scvb, sys_code_b scb WHERE scb.CODE = 'PRJ_CHECK_REGULAR_ASSIGN' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y' AND scvb.VALUE= p.PRJ_REGULAR_ASSIGN ) PRJ_REGULAR_ASSIGN_N, p.ASSIGN_STATUS, ( SELECT scvb.meaning AS value_name FROM sys_code_value_b scvb, sys_code_b scb WHERE scb.CODE = 'PRJ_ASSIGN_STATUS' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y' AND scvb.VALUE= p.ASSIGN_STATUS ) ASSIGN_STATUS_N, p.EMPLOYEE_ID, p.CONTRACT_START_DATE, p.plan_number, (select s.description from sys_user s where s.user_id = p.EMPLOYEE_ID) employee_id_n, ( SELECT pp.contract_name FROM prj_project pp WHERE pp.project_id = p.contract_id ) contract_name, ( SELECT b.bp_name FROM prj_project pp, hls_bp_master b WHERE pp.tenant_id = b.bp_id AND pp.project_id = p.contract_id ) bp_name, ( SELECT pp.tenant_id FROM prj_project pp WHERE pp.project_id = p.contract_id ) bp_id, ( SELECT fea.unit_id FROM fnd_employee_assigns fea WHERE fea.employee_id = p.employee_id and fea.PRIMARY_POSITION_FLAG = 'Y' ) unit_id, ( SELECT pp.HOST_PROJECT_MANAGER FROM prj_project pp WHERE pp.project_id = p.contract_id ) HOST_PROJECT_MANAGER, ( SELECT pp.ASSIST_PROJECT_MANAGER FROM prj_project pp WHERE pp.project_id = p.contract_id ) ASSIST_PROJECT_MANAGER FROM prj_check_plan p)t1
t1.plan_id in ( SELECT max(cp.plan_id) plan_id FROM "PRJ_CHECK_PLAN" cp left join prj_project p on p.project_id = cp.contract_id group by p.tenant_id,cp.plan_check_date )
and ( t1.unit_id = (SELECT fea.unit_id from sys_user_allocation sua, fnd_employee_assigns fea where sua.EMPLOYEE_ASSIGN_ID = fea.EMPLOYEE_ASSIGN_ID and sua.user_id =#{request.userId}) or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE = 'ADMIN' and U.USER_ID = #{createdBy}) OR T1.HOST_PROJECT_MANAGER = #{createdBy} or T1.ASSIST_PROJECT_MANAGER = #{createdBy} )
AND t1.PLAN_ID = #{planId}
AND t1.CONTRACT_NUMBER = #{contractNumber}
AND t1.contract_name like concat('%',concat(#{contractName},'%'))
and t1.CONTRACT_START_DATE >= #{contractStartDateFrom}
and t1.CONTRACT_START_DATE <= #{contractStartDateTo}
and to_char(t1.PLAN_CHECK_DATE,'yyyy-mm-dd') >= #{planCheckDateFrom}
and to_char(t1.PLAN_CHECK_DATE,'yyyy-mm-dd') <= #{planCheckDateTo}
and t1.employee_id_n like concat('%',concat(#{employeeIdN},'%'))
and t1.bp_name like concat('%',concat(#{bpName},'%'))
and t1.ASSIGN_STATUS = #{assignStatus}
and t1.bp_id = #{bpId}
order by t1.plan_id desc
